inline FrameTailState state(const Case& c){FrameTailState out{c.loop,{100,-250,0},0,0,{},{}};for(int i=0;i<4;++i){out.actors.push_back({29,{1000+i*100,2000,0}});}if(c.craft){out.actors.push_back({7,{12345,-28000,5000}});}return out;}
inline Level1ArrivalInput input(const Case& c){Level1ArrivalInput out{c.flag,c.craft?std::optional<std::size_t>{0}:std::nullopt,{}, {},{static_cast<std::int16_t>(c.craft?1:0),c.spawned,10,static_cast<std::uint16_t>(c.craft?5:4),6,{}}};out.player.position={100,-250,0};out.pool.ordinaryPool[0]={static_cast<std::uint8_t>(c.craft?100:0),false,0};out.pool.ordinaryPool[1]={0,false,1};return out;}
inline FrameTailGuards guards(const Case& c,const StellarRng& rng){FrameTailGuards g{600,{},{},0x1e,0x1e,false,false,false,false,false,true,{}};if((c.loop&15)==0){g.periodic=FrameTailPeriodicInput{0,static_cast<std::int16_t>(c.craft?1:0),c.spawned,10,campaignSpawnThreshold(0,c.craft?1:0),rng.indexA(),rng.indexB(),c.flag};}return g;}
inline Level1ArrivalTailWork run(const Case& c){StellarRng rng(std::array<std::uint16_t,56>{},48,110,0,0);const auto n=static_cast<std::size_t>(c.craft?5:4);return level1ArrivalFrameTailOperations(state(c),guards(c,rng),rng,input(c),arrival_fixture::models(),{n,n,0});}
inline std::pair<Ops,Ops> split(const Level1ArrivalTailWork& w){Ops before,after;bool found=false;assert(w.periodic.tail.beforeEntryFade.empty());for(const auto op:w.periodic.tail.afterEntryFade){if(op.kind==NormalWorkKind::gameplayArrivalEvent){assert(!found&&op.count==1&&op.value==17);found=true;}else{(found?after:before).push_back(op);}}return {before,after};}
